func ptNl(b []byte, i int32) int32 {
	// Index of the next newline at or after i, or the blob's length.
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func ptTab(b []byte, i int32, lim int32) int32 {
	// Index of the next tab in [i, lim), or lim.
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func ptHexval(c int32) int32 {
	if (c >= 48) && (c <= 57) {
		return c - 48
	}
	if (c >= 97) && (c <= 102) {
		return c - 87
	}
	if (c >= 65) && (c <= 70) {
		return c - 55
	}
	return -1
}

func ptDec(b []byte, from int32, to int32) int32 {
	var k int32 = from
	var v int32 = 0
	for k < to {
		v = (v * 10) + (port.BlobU8(b, k) - 48)
		k += 1
	}
	return v
}

func ptUnescape(b []byte, from int32, to int32, out *port.Cells) int32 {
	// b[from, to) with \n \r \t \\ and \xHH turned into bytes, into out.
	var k int32 = from
	var c int32 = 0
	port.CellsDrop(out, 0)
	for k < to {
		c = port.BlobU8(b, k)
		k += 1
		if c == 92 {
			c = port.BlobU8(b, k)
			k += 1
			if c == 110 {
				port.CellsPush(out, 10)
			}
			if c == 114 {
				port.CellsPush(out, 13)
			}
			if c == 116 {
				port.CellsPush(out, 9)
			}
			if c == 92 {
				port.CellsPush(out, 92)
			}
			if c == 120 {
				port.CellsPush(out, (ptHexval(port.BlobU8(b, k))*16)+ptHexval(port.BlobU8(b, k+1)))
				k += 2
			}
		} else {
			port.CellsPush(out, c)
		}
	}
	return port.CellsLen(out)
}

func ptDoRow(f []byte, from int32, to int32, indirect int32, inp *port.Cells, ar *port.Cells, t *strings.Builder) int32 {
	// Unescape the row's input, parse it, and write its dump (or
	// `!status`) to t.
	var h int32 = 0
	ptUnescape(f, from, to, inp)
	pdflex.PlInit(ar)
	pdflex.PlSeek(ar, 0, port.CellsLen(inp))
	if indirect == 1 {
		h = pdflex.PlParseIndirect(port.SrcOfBlob(port.CellsBlob(inp)), ar, 0)
	} else {
		h = pdflex.PlParse(port.SrcOfBlob(port.CellsBlob(inp)), ar)
	}
	if h == 0 {
		port.TextAscii(t, "!")
		pdflex.PlStatusEmitName(t, pdflex.PlErr(ar))
	} else {
		pdflex.PlDump(t, ar, h)
	}
	return h
}

func ptRowFields(f []byte, pos int32, e int32, which int32) int32 {
	// The tab positions of the row at [pos, e): which 0..3.
	var s0 int32 = ptTab(f, pos, e)
	var s1 int32 = ptTab(f, s0+1, e)
	var s2 int32 = ptTab(f, s1+1, e)
	if which == 0 {
		return s0
	}
	if which == 1 {
		return s1
	}
	if which == 2 {
		return s2
	}
	return ptTab(f, s2+1, e)
}

func ptIsRow(f []byte, pos int32, e int32) int32 {
	// 0 for a blank line, a comment or a directive.
	if pos >= e {
		return 0
	}
	if port.BlobU8(f, pos) == 35 {
		return 0
	}
	if port.BlobU8(f, pos) == 33 {
		return 0
	}
	return 1
}

func ptMode(f []byte, pos int32, e int32, old int32) int32 {
	// The mode after the line at pos: 1 after `!indirect`, 0 after
	// `!direct`, otherwise unchanged.
	if pos >= e {
		return old
	}
	if port.BlobU8(f, pos) != 33 {
		return old
	}
	if port.BlobU8(f, pos+1) == 105 {
		return 1
	}
	return 0
}

func ptRows(f []byte) int32 {
	// The number of rows in a corpus file.
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var e int32 = 0
	var rows int32 = 0
	for pos < n {
		e = ptNl(f, pos)
		rows += ptIsRow(f, pos, e)
		pos = e + 1
	}
	return rows
}

func TestEveryRowOfTheObjectCorpus(emonT *testing.T) {
	var f []byte = port.TestFile("pdf/objects.txt")
	var inp *port.Cells = port.NewCells()
	var ar *port.Cells = port.NewCells()
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var indirect int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	var s2 int32 = 0
	var s3 int32 = 0
	for pos < n {
		line += 1
		e = ptNl(f, pos)
		indirect = ptMode(f, pos, e, indirect)
		if ptIsRow(f, pos, e) == 1 {
			s0 = ptRowFields(f, pos, e, 0)
			s1 = ptRowFields(f, pos, e, 1)
			s2 = ptRowFields(f, pos, e, 2)
			s3 = ptRowFields(f, pos, e, 3)
			var t *strings.Builder = port.NewText()
			var h int32 = ptDoRow(f, pos, s0, indirect, inp, ar, t)
			port.AssertThatAt(emonT, h >= 0, "parsed", line)
			port.AssertTextSpan(emonT, t, f, s0+1, s1, "object dump", line)
			if s1 < e {
				port.AssertEqAt(emonT, pdflex.PlPos(ar), ptDec(f, s1+1, s2), "end position", line)
			}
			if s2 < e {
				port.AssertEqAt(emonT, pdflex.PlWarn(ar), ptDec(f, s2+1, s3), "warning bits", line)
			}
		}
		pos = e + 1
	}
	port.AssertThat(emonT, ptRows(f) > 150, "the corpus was read")
}

