func ptParseText(b []byte, ar *port.Cells) int32 {
	pdflex.PlInit(ar)
	pdflex.PlSeek(ar, 0, port.BlobLen(b))
	return pdflex.PlParse(port.SrcOfBlob(b), ar)
}

func TestNamesAreInternedAndWellKnownIdsResolve(emonT *testing.T) {
	var ar *port.Cells = port.NewCells()
	var d int32 = ptParseText(port.TextBlob("<</Type /Page /Kids [1 0 R] /Type#20X /Type /Media#42ox [0 0 612.5 792]>>"), ar)
	var ty int32 = pdflex.PlDictGet(ar, d, pdfnames.PnType())
	var kids int32 = pdflex.PlDictGet(ar, d, pdfnames.PnKids())
	var mb int32 = pdflex.PlDictGet(ar, d, pdfnames.PnMediaBox())
	var kid0 int32 = pdflex.PlFirst(ar, kids)
	port.AssertThat(emonT, d != 0, "parsed")
	port.AssertEq(emonT, pdflex.PlKindOf(ar, d), pdflex.PlKDict(), "a dictionary")
	port.AssertEq(emonT, pdflex.PlKindOf(ar, ty), pdflex.PlKName(), "/Type is a name")
	port.AssertThat(emonT, pdflex.PlNameIs(ar, ty, pdfnames.PnType()) == 0, "/Page is not /Type")
	port.AssertEq(emonT, pdflex.PlDictGet(ar, d, pdfnames.PnLength()), 0, "an absent key answers 0")
	port.AssertEq(emonT, pdflex.PlKindOf(ar, kids), pdflex.PlKArray(), "/Kids is an array")
	port.AssertEq(emonT, pdflex.PlCount(ar, kids), 1, "one kid")
	port.AssertEq(emonT, pdflex.PlKindOf(ar, kid0), pdflex.PlKRef(), "a reference")
	port.AssertEq(emonT, pdflex.PlIntValue(ar, kid0), 1, "to object 1")
	// `/Media#42ox` is `/MediaBox`: the escape is decoded BEFORE interning.
	port.AssertThat(emonT, mb != 0, "/Media#42ox finds /MediaBox")
	port.AssertEq(emonT, pdflex.PlCount(ar, mb), 4, "four numbers")
	// The first /Type is /Page, the key written twice is /Type#20X, and
	// the last /Type wins: its value is the LAST one.
	port.AssertEq(emonT, pdflex.PlKindOf(ar, ty), pdflex.PlKName(), "last /Type")
}

