func TestEveryTruncationOfAFixtureParsesOrNamesAnError(emonT *testing.T) {
	var f []byte = port.TestFile("pdf/minimal.pdf")
	var n int32 = port.BlobLen(f)
	var cut *port.Cells = port.NewCells()
	var ar *port.Cells = port.NewCells()
	var cutn int32 = 0
	var i int32 = 0
	var guard int32 = 0
	var at int32 = 0
	var h int32 = 0
	var before int32 = 0
	for cutn < (n + 1) {
		port.CellsDrop(cut, 0)
		i = 0
		for i < cutn {
			port.CellsPush(cut, port.BlobU8(f, i))
			i += 1
		}
		// As a token-level object stream from 0.
		pdflex.PlInit(ar)
		pdflex.PlSeek(ar, 0, cutn)
		guard = 0
		h = 1
		for (h != 0) && (guard < 2000) {
			before = pdflex.PlPos(ar)
			h = pdflex.PlParse(port.SrcOfBlob(port.CellsBlob(cut)), ar)
			if (h != 0) && (pdflex.PlPos(ar) <= before) {
				h = 0
			}
			guard += 1
		}
		// And as an indirect object at the start of every line.
		at = 0
		for at < cutn {
			pdflex.PlInit(ar)
			pdflex.PlSeek(ar, 0, cutn)
			pdflex.PlParseIndirect(port.SrcOfBlob(port.CellsBlob(cut)), ar, at)
			// a stream's data ends inside the blob
			port.AssertThat(emonT, pdflex.PlPos(ar) <= cutn, "the parse never ran past the end")
			at = ptNl(f, at) + 1
		}
		cutn += 1
	}
}
